import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------------
# CUDA kernel (inline extension)
# ------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void conv1d_kernel(const half* __restrict__ input,
                              const half* __restrict__ weight,
                              half* __restrict__ output,
                              int batch,
                              int in_c,
                              int out_c,
                              int length,
                              int kernel_size,
                              int stride,
                              int dilation,
                              int out_len) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * out_c * out_len;
    if (idx >= total) return;

    int o  = idx % out_len;                         // output position
    int oc = (idx / out_len) % out_c;               // output channel
    int b  = idx / (out_len * out_c);               // batch index

    float acc = 0.0f;
    for (int ic = 0; ic < in_c; ++ic) {
        for (int k = 0; k < kernel_size; ++k) {
            int in_pos = o * stride + k * dilation;    // input position
            int input_idx  = b * (in_c * length) + ic * length + in_pos;
            int weight_idx = oc * (in_c * kernel_size) + ic * kernel_size + k;
            acc += __half2float(input[input_idx]) * __half2float(weight[weight_idx]);
        }
    }
    int out_idx = b * (out_c * out_len) + oc * out_len + o;
    output[out_idx] = __float2half(acc);
}

void conv1d_forward_cuda(torch::Tensor input,
                         torch::Tensor weight,
                         torch::Tensor output,
                         int stride,
                         int dilation) {
    const int batch      = input.size(0);
    const int in_c       = input.size(1);
    const int length     = input.size(2);
    const int out_c      = weight.size(0);
    const int kernel_sz  = weight.size(2);
    const int out_len    = output.size(2);

    const int threads = 256;
    const int total   = batch * out_c * out_len;
    const int blocks  = (total + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "conv1d_forward_cuda", ([&] {
        conv1d_kernel<<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            weight.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            batch, in_c, out_c, length,
            kernel_sz, stride, dilation, out_len);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
}
'''

# Build the inline extension
conv1d_cuda = load_inline(name='conv1d_cuda',
                          cpp_sources='',
                          cuda_sources=cuda_source,
                          functions=['conv1d_forward_cuda'],
                          verbose=False)

# ------------------------------------------------------------------
# ModelNew – drop‑in replacement for the reference Model
# ------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    1‑D convolution implemented with a custom CUDA kernel.
    All tensors are fp16; accumulation uses float32.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 dilation: int = 1,
                 bias: bool = False):
        super().__init__()
        self.stride = stride
        self.dilation = dilation

        # weight: (out_channels, in_channels, kernel_size)
        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels, kernel_size,
                        dtype=torch.float16, device='cuda')
        )
        # Kaiming uniform initialization (same as nn.Conv1d)
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

        if bias:
            self.bias = nn.Parameter(
                torch.empty(out_channels, dtype=torch.float16, device='cuda')
            )
            fan_in = in_channels * kernel_size
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        x: (batch, in_channels, length)  – must be fp16 and on CUDA
        Returns: (batch, out_channels, out_length)  – fp16
        """
        if x.dtype != torch.float16:
            raise TypeError('Input tensor must be float16')
        if not x.is_cuda:
            raise RuntimeError('Input tensor must be on CUDA')

        batch, _, length = x.shape
        k = self.weight.shape[2]

        # Compute output length exactly as nn.Conv1d does (no padding)
        out_len = (length - (k - 1) * self.dilation - 1) // self.stride + 1

        out = torch.empty(batch,
                          self.weight.shape[0],
                          out_len,
                          dtype=torch.float16,
                          device='cuda')

        # Launch custom kernel
        conv1d_cuda.conv1d_forward_cuda(x, self.weight, out,
                                        self.stride, self.dilation)

        if self.bias is not None:
            out = out + self.bias.view(1, -1, 1)
        return out
